/* presets.js: the preset picker (PRD section 7, K-24).
 *
 * Idea: the six presets are plain data in presets_data.js (generated by
 * tools/gen_workload.py, so no network call and it works from file://). This
 * file only copies one preset into the store: machine capacities, aging
 * settings and the job list. It never decides which job runs.
 *
 * Classic script: attaches APRM.presets only.
 */
(function () {
  'use strict';

  var APRM = (window.APRM = window.APRM || {});

  /* The preset data array (empty if presets_data.js did not load). */
  function all() {
    return Array.isArray(APRM.presetsData) ? APRM.presetsData : [];
  }

  /* Look one preset up by its name; null if there is none. O(presets). */
  function find(name) {
    var list = all();
    for (var i = 0; i < list.length; i++) { if (list[i].name === name) { return list[i]; } }
    return null;
  }

  /* Put preset `name` into the store (machine, aging settings, jobs). Jobs are
   * copied, so editing the table never changes the preset data. Returns the
   * preset, or null when the name is unknown. O(jobs). */
  function load(name) {
    var p = find(name);
    if (p === null) { return null; }
    var jobs = [];
    for (var i = 0; i < p.jobs.length; i++) {
      var j = p.jobs[i];
      jobs.push({ id: j.id, arrival: j.arrival, duration: j.duration, cpu: j.cpu, mem: j.mem, priority: j.priority });
    }
    APRM.store.setMachine(p.cpu_cap, p.mem_cap);
    APRM.store.setSettings({ alphaMilli: p.alpha_milli, threshold: p.threshold });
    APRM.store.setJobs(jobs);
    return p;
  }

  var mounted = false;

  /* Fill the picker and wire its button. Missing elements are skipped. */
  function mount() {
    if (mounted) { return; }
    mounted = true;
    var select = document.getElementById('preset-select');
    var button = document.getElementById('preset-load');
    var desc = document.getElementById('preset-desc');
    var list = all();
    if (!select) { return; }
    if (list.length === 0) {
      if (desc) { desc.textContent = 'No presets are available (js/presets_data.js did not load).'; desc.hidden = false; }
      if (button) { button.disabled = true; }
      return;
    }
    for (var i = 0; i < list.length; i++) {
      var opt = document.createElement('option');
      opt.setAttribute('value', list[i].name);
      opt.textContent = list[i].title;
      select.appendChild(opt);
    }
    function describe() {
      var p = find(select.value);
      if (desc) { desc.textContent = p ? p.description : ''; desc.hidden = !p; }
    }
    select.addEventListener('change', describe);
    if (button) {
      button.addEventListener('click', function () {
        if (load(select.value) !== null) { describe(); }
      });
    }
    if (!select.value) { select.value = list[0].name; }
    describe();
  }

  APRM.presets = { all: all, find: find, load: load, mount: mount };
})();
